"""Built-in operation order.

What: the order the catalog had before each operation moved into its own file.
Where: app/modules/order.py. The catalog sorts with sort_key.
Why: a new module appends its operations. Built-in ids stay where API clients already saw them.
"""

from __future__ import annotations

