def sort_key(operation_id: str) -> tuple[int, str]:
    """Known ids keep their old place. Anything else sorts after them."""
    try:
        return (CATALOG_ORDER.index(operation_id), "")
    except ValueError:
        return (len(CATALOG_ORDER), operation_id)

